element.event:
local transitionTimer = element:parent()("transitionTimer"):GetFloat() local transitionStart = element("transitionStart"):GetFloat() local transitionLength = element("transitionLength"):GetFloat()
if((transitionTimer >= transitionStart) and (transitionTimer <= (transitionStart+transitionLength))) then element("xOffset"):SetInt((-160*(lua_sys.screenWidth()/480.0)*(transitionTimer-transitionStart))/transitionLength)
if element("transitionStarted"):GetInt() == 0 then lua_sys.playSoundFx("audio/sfx/menu_slide.wav") element("transitionStarted"):SetInt(1) end else if(transitionTimer < transitionStart) then element("xOffset"):SetInt(30*game.hudScale())
else element("xOffset"):SetInt(-160*(lua_sys.screenWidth()/480.0)) end end
